const fs = require("fs");
const html = fs.readFileSync("index.html", "utf8");
const script = html.match(/<script>([\s\S]*)<\/script>/)[1];
const pure = script.split("// ---- Render ----")[0];

// 1) Embedded CSV must match the file exactly
const csvBlock = pure.match(/const CSV = `([\s\S]*?)`;/)[1].trim();
const csvFile = fs.readFileSync("anc4_coverage.csv", "utf8").trim();
console.log("Embedded CSV identical to anc4_coverage.csv:", csvBlock === csvFile);

// 2) Run the page's own parse + math
const api = new Function(pure + "; return { rows, districts, years, sources, rate, aggregate, rowFor };")();
console.log("rows parsed:", api.rows.length, "| districts:", api.districts.join(","), "| years:", api.years.join(","), "| sources:", api.sources.join("|"));
for (const y of api.years) {
  const agg = api.aggregate(y);
  const list = api.districts.map(d => { const r = api.rowFor(d, y); return d + " " + (r.anc4 / r.reg * 100).toFixed(1) + "%"; });
  console.log(y, "all-district:", (agg.anc4 / agg.reg * 100).toFixed(1) + "% (" + agg.anc4 + "/" + agg.reg + ")", "|", list.join("  "));
}

// 3) Independently recompute from the CSV file and compare
const expected = {};
csvFile.split("\n").slice(1).forEach(line => {
  const [d, y, reg, anc4] = line.split(",");
  expected[d + "|" + y] = anc4 / reg * 100;
});
let ok = true;
for (const r of api.rows) {
  const e = expected[r.district + "|" + r.year];
  if (Math.abs(api.rate(r) - e) > 1e-9) { ok = false; console.error("MISMATCH", r.district, r.year); }
}
console.log("All page rates match independent CSV computation:", ok);

// 4) Check HTML has all required elements
const need = ["yearSelector", "chart", "dataTable", "sourceList", "syntheticNote", "calcExample", "trendTh", "footerNote"];
console.log("Required element ids present:", need.every(id => html.includes('id="' + id + '"')));

